"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { userService } from "@/lib/services/user-service";
import { UserResponse } from "@/components/types";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
  DetailLayout,
  DetailSection,
  DetailItem,
} from "@/components/layouts/detail-layout";
import { toast } from "sonner";
import { Mail, Phone, User as UserIcon, Building } from "lucide-react";
import { getImageUrl } from "@/lib/utils";

export default function UserDetailPage() {
  const { id } = useParams();
  const router = useRouter();
  const [user, setUser] = useState<UserResponse | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (id) {
      loadData();
    }
  }, [id]);

  const loadData = async () => {
    try {
      setLoading(true);
      const response = await userService.getUserById(id as string);
      if (response.data) {
        setUser(response.data);
      } else {
        toast.error("User not found");
      }
    } catch (err) {
      console.error(err);
      toast.error("Failed to load user details");
    } finally {
      setLoading(false);
    }
  };

  const handleToggleStatus = async () => {
    if (!user) return;
    if (
      !confirm(
        `Are you sure you want to ${
          user.status === "ACTIVE" ? "disable" : "activate"
        } this user?`
      )
    )
      return;

    try {
      const loadingToast = toast.loading("Updating status...");
      await userService.toggleUserStatus(user.id);
      toast.success("Status updated successfully", { id: loadingToast });
      loadData();
    } catch (error) {
      toast.error("Failed to update status");
    }
  };

  const formatDateTime = (date?: Date | string) =>
    date ? new Date(date).toLocaleString() : "—";

  if (loading) {
    return <div className="p-10 text-center">Loading user details...</div>;
  }

  if (!user) {
    return <div className="p-10 text-center text-red-500">User not found</div>;
  }

  return (
    <DetailLayout
      backLink={{ label: "User Management", href: "/dashboard/users" }}
      title="User Profile"
      subtitle={`ID: ${String(user.id || "")
        .substring(0, 12)
        .toUpperCase()}`}
      actions={
        <div className="flex items-center gap-3">
          <Button
            variant="ghost"
            onClick={handleToggleStatus}
            className="bg-slate-100 hover:bg-slate-200 text-slate-900 rounded-xl h-10 px-4 font-bold transition-all border border-slate-200"
          >
            {user.status === "ACTIVE" ? "Disable Account" : "Activate Account"}
          </Button>
          <Button
            variant="ghost"
            onClick={() => router.push(`/dashboard/users/${user.id}/edit`)}
            className="bg-slate-100 hover:bg-slate-200 text-slate-900 rounded-xl h-10 px-4 font-bold transition-all"
          >
            Edit Profile
          </Button>
          <Badge
            className={`h-10 px-5 rounded-xl flex items-center justify-center font-black uppercase text-[10px] tracking-widest border-none ${
              user.status === "ACTIVE"
                ? "bg-green-100 text-green-700"
                : "bg-red-100 text-red-700"
            }`}
          >
            {String(user.status || "")}
          </Badge>
        </div>
      }
    >
      <DetailSection title="Staff Profile">
        <div className="col-span-1 md:col-span-2 lg:col-span-1 row-span-2">
          <div className="relative aspect-square w-40 rounded-2xl overflow-hidden border border-slate-100 shadow-sm mx-auto lg:mx-0">
            <Avatar className="h-full w-full">
              <AvatarImage src={getImageUrl(user.profileImage)} />
              <AvatarFallback className="bg-primary/5 text-primary text-4xl font-black">
                {String(user.fullName || "")
                  .split(" ")
                  .map((n) => n[0])
                  .join("") || <UserIcon className="h-16 w-16" />}
              </AvatarFallback>
            </Avatar>
          </div>
        </div>

        <div className="col-span-1 md:col-span-2 lg:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-6">
          <DetailItem label="Full Name" value={String(user.fullName || "")} />
          <DetailItem
            label="User Role"
            value={
              <Badge
                variant="outline"
                className="uppercase tracking-wider font-bold"
              >
                {String(user.role || "").replace("_", " ")}
              </Badge>
            }
          />

          <DetailItem
            label="Email Address"
            value={
              <div className="flex items-center gap-2">
                <Mail className="h-4 w-4 text-slate-400" />
                {String(user.email || "")}
              </div>
            }
          />
          <DetailItem
            label="Phone Number"
            value={
              <div className="flex items-center gap-2">
                <Phone className="h-4 w-4 text-slate-400" />
                {user.phoneNumber ? String(user.phoneNumber) : "Not provided"}
              </div>
            }
          />
        </div>
      </DetailSection>

      <DetailSection title="User account Status">
        <DetailItem
          label="Account Status"
          value={
            user.isPasswordSet || user.isEmailVerified || user.isPhoneVerified
              ? "Account Active"
              : "Pending"
          }
        />
        <DetailItem
          label="Registration Date"
          value={formatDateTime(user.createdAt)}
        />
        <DetailItem
          label="Last Updated"
          value={formatDateTime(user.updatedAt)}
        />
      </DetailSection>
    </DetailLayout>
  );
}
